prompt --application/shared_components/workflow/task_definitions/employee_self_appraisal
begin
wwv_flow_imp_shared.create_task_def(
 p_id=>wwv_flow_imp.id(25733150955339389279)
,p_name=>'Employee Self Appraisal'
,p_static_id=>'EMPLOYEE_SELF_APPRAISAL'
,p_subject=>'Employee Self Appraisal for &ENAME.'
,p_task_type=>'APPROVAL'
,p_priority=>3
,p_expiration_policy=>'NONE'
,p_max_renewal_count=>3
,p_details_link_target=>'f?p=&APP_ID.:18:&SESSION.::&DEBUG.:RP,18:P18_TASK_ID:&TASK_ID.'
,p_actions_sql_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select initcap(e.ename) ename, e.empno empno ',
'   from act_emp e ',
'   join act_review r ',
'   on r.empno = e.empno ',
'   where r.review_id = :APEX$TASK_PK'))
,p_initiator_can_complete=>false
);
wwv_flow_imp_shared.create_task_def_action(
 p_id=>wwv_flow_imp.id(25740512104481788092)
,p_task_def_id=>wwv_flow_imp.id(25733150955339389279)
,p_name=>'Update Review Status to REQUESTED'
,p_execution_sequence=>10
,p_on_event=>'CREATE'
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    update act_review',
'    set status = ''REQUESTED''',
'    where review_id = :APEX$TASK_PK;',
'end;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
);
wwv_flow_imp_shared.create_task_def_action(
 p_id=>wwv_flow_imp.id(25741304423482796428)
,p_task_def_id=>wwv_flow_imp.id(25733150955339389279)
,p_name=>'Update Review Status to SUBMITTED'
,p_execution_sequence=>20
,p_on_event=>'COMPLETE'
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    update act_review',
'    set status = ''SUBMITTED''',
'    where review_id = :APEX$TASK_PK;',
'end;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
);
