'    apex.server.process("GET_PROGRESS", {}, {',
'        success: function(data) {',
'            var progressValue = data.prog_value; ',
'            var progressBar = document.getElementById("progress-bar");',
'',
'            // Update width and text',
'            progressBar.style.width = progressValue + "%";',
'            progressBar.textContent = progressValue + "%";',
'        }',
'    });',
'}, 2); ',
''))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(26857110785551120847)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'New'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  htp.p(''Starting Process'');',
'  FOR i IN 1..10 LOOP',
'    htp.p(i || '' second(s) passed'');',
'    APEX_UTIL.PAUSE(1);',
'  END LOOP;',
'  htp.p(''Process Completed'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Success'
,p_internal_uid=>26857110785551120847
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(70584083623544665012)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Progress Checking'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_session_id VARCHAR2(100) := :APP_USER || ''_'' || TO_CHAR(SYSTIMESTAMP, ''YYYYMMDDHH24MISS''); -- Unique session ID',
'BEGIN',
'    -- Insert initial progress into the table',
'    INSERT INTO PROCESS_PROGRESS (SESSION_ID, PROGRESS_VALUE)',
'    VALUES (l_session_id, 0);',
'    COMMIT;',
'',
'    -- Step 1: Simulate Fetching Data',
'    APEX_UTIL.PAUSE(1);',
'    UPDATE PROCESS_PROGRESS',
'    SET PROGRESS_VALUE = 25, LAST_UPDATED = SYSTIMESTAMP',
'    WHERE SESSION_ID = l_session_id;',
'    COMMIT;',
'',
'    -- Step 2: Simulate Inserting Data',
'    APEX_UTIL.PAUSE(1);',
'    UPDATE PROCESS_PROGRESS',
'    SET PROGRESS_VALUE = 50, LAST_UPDATED = SYSTIMESTAMP',
'    WHERE SESSION_ID = l_session_id;',
'    COMMIT;',
'',
'    -- Step 3: Simulate Updating Data',
'APEX_UTIL.PAUSE(1);',
'    UPDATE PROCESS_PROGRESS',
'    SET PROGRESS_VALUE = 75, LAST_UPDATED = SYSTIMESTAMP',
'    WHERE SESSION_ID = l_session_id;',
'    COMMIT;',
'',
'    -- Step 4: Finalize the Process',
'APEX_UTIL.PAUSE(1);',
'    UPDATE PROCESS_PROGRESS',
'    SET PROGRESS_VALUE = 100, LAST_UPDATED = SYSTIMESTAMP',
'    WHERE SESSION_ID = l_session_id;',
'    COMMIT;',
'',
'    -- Optional: Clean up progress tracker for this session',
'APEX_UTIL.PAUSE(1);',
'    DELETE FROM PROCESS_PROGRESS WHERE SESSION_ID = l_session_id;',
'    COMMIT;',
'EXCEPTION WHEN OTHERS THEN',
'raise_application_error(-20001,sqlerrm);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(70584083745467665013)
,p_process_success_message=>'Success'
,p_internal_uid=>70584083623544665012
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(79880465036730768401)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_PROGRESS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    DECLARE',
'        l_progress NUMBER:=0;',
'    BEGIN',
'        -- Fetch progress value from the table',
'       SELECT PROGRESS_VALUE',
'        INTO l_progress',
'        FROM PROCESS_PROGRESS',
'        WHERE SESSION_ID = :APP_SESSION;',
'',
'        -- Return progress as JSON',
'        APEX_JSON.OPEN_OBJECT;',
'        APEX_JSON.WRITE(''prog_value'', l_progress);',
'        APEX_JSON.CLOSE_OBJECT;',
'         EXCEPTION WHEN NO_DATA_FOUND THEN',
'    l_progress := 0;',
'',
'    END;',
'   ',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>79880465036730768401
);
end;
/
