,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'New'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 6/12/2024 12:39:38 AM (QP5 v5.360) */',
'DECLARE',
'    vFileName    VARCHAR2 (100);',
'    vfileType    VARCHAR2 (200);',
'    vFileCont    BLOB;',
'    l_zip_file   BLOB;',
'BEGIN',
'    BEGIN',
'        SELECT FILENAME, MIME_TYPE, BLOB_CONTENT',
'          INTO vFileName, vfileType, vFileCont',
'          FROM APEX_230200.WWV_FLOW_FILES',
'         WHERE NAME = :P4_UPLOAD_FILES;',
'    EXCEPTION',
'        WHEN OTHERS',
'        THEN',
'            NULL;',
'    END;',
'',
'',
'',
'    BEGIN',
'        FOR l_file',
'            IN (SELECT FILENAME file_name, BLOB_CONTENT file_content',
'                  FROM WWV_FLOW_FILES)',
'        LOOP',
'            apex_zip.add_file (p_zipped_blob   => l_zip_file,',
'                               p_file_name     => l_file.file_name,',
'                               p_content       => l_file.file_content);',
'        END LOOP;',
'',
'        apex_zip.finish (p_zipped_blob => l_zip_file);',
'    END;',
'INSERT INTO WKSP_AYUBWP.IMAGE_TEST (',
'    IMAGE_ID,',
'    IMAGE',
') VALUES (',
'    9999,',
'    l_zip_file',
');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>125900937331915574603
);
end;
