,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_region_id=>wwv_flow_imp.id(6438296667478047010)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CHK_ENAME_EXST'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 10/27/2021 3:23:10 PM (QP5 v5.360) */',
'DECLARE',
'    CURSOR chk_ename (p_cur_ename IN CUSTOMERS.FULL_NAME%TYPE)',
'    IS',
'        SELECT 1',
'          FROM CUSTOMERS',
'         WHERE FULL_NAME = p_cur_ename;',
'',
'    lv_cnt   NUMBER;',
'BEGIN',
'    OPEN chk_ename (p_cur_ename => APEX_APPLICATION.g_x01);',
'',
'    FETCH chk_ename INTO lv_cnt;',
'',
'    CLOSE chk_ename;',
'',
'    IF lv_cnt = 1',
'    THEN',
'        HTP.prn (''Y'');',
'    ELSE',
'        HTP.prn (''N'');',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>2860626864111791313
);
end;
