begin
wwv_flow_imp_page.create_page(
 p_id=>7
,p_name=>'Checking Sweet Alert'
,p_alias=>'CHECKING-SWEET-ALERT'
,p_step_title=>'Checking Sweet Alert'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function showSaveAlert(buttonId) {',
'  // First, display the SweetAlert dialog',
' var vTitle;',
'  if (apex.item("P7_NEW").getValue() == "") { ',
'    vTitle = ''Do you want to submit with null?''; ',
'  } else {',
'    vTitle = ''Do you want to save the changes?''; ',
'  }',
'  Swal.fire({',
'    title: vTitle,',
'    showDenyButton: true,',
'    showCancelButton: true,',
'    confirmButtonText: "Save",',
'    denyButtonText: `Don''t save`',
'  }).then((result) => {',
'    if (result.isConfirmed) {',
'      // Call an APEX process to check for errors',
'      apex.server.process("ABC_PROCESS", {}, {',
'        dataType: "text",',
'        success: function (data) {',
'          if (data) {',
'            // If there''s an error message, display it in SweetAlert',
'            Swal.fire({',
'              icon: ''error'',',
'              title: ''Fault:'',',
'              text: data,',
'            });',
'          } else {',
'            // If no errors, trigger the APEX button action',
'            ',
'            Swal.fire("Saved Successfully!", "", "success").then(() => {',
'              apex.event.trigger(buttonId, ''click''); // Trigger the APEX button''s click event',
'            });',
'          }',
'        },',
'        error: function (xhr, status, error) {',
'          // Handle any unexpected errors in the AJAX call itself',
'          Swal.fire({',
'            icon: ''error'',',
'            title: ''Unexpected Error'',',
'            text: ''An unexpected error occurred: '' + error,',
'          });',
'        }',
'      });',
'    } else if (result.isDenied) {',
'      Swal.fire("Changes are not saved", "", "info");',
'    }',
'  });',
'}',
''))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'17'
);
