,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>30
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_json CLOB :=''{',
'	"success": true,',
'	"message": null,',
'	"payload": {',
'		"provider": {',
'			"providerId": 9,',
'			"providerName": "DESCO PostPaid",',
'			"category": null,',
'			"categoryID": 0',
'		},',
'		"actionName": "Check",',
'		"fields": [',
'			{',
'				"fieldID": 92,',
'				"label": "Bill Number",',
'				"type": "text",',
'				"mode": "input",',
'				"value": null,',
'				"isRequired": true,',
'				"action": "Check",',
'				"isBeneficiaryCode": false,',
'				"isTransferAmount": false,',
'				"isHidden": false,',
'				"allowPartialPayment": false,',
'				"pattern": null,',
'				"hint": null,',
'				"listItems": null',
'			},',
'			{',
'				"fieldID": 93,',
'				"label": "Account Number",',
'				"type": "text",',
'				"mode": "input",',
'				"value": null,',
'				"isRequired": false,',
'				"action": "Check",',
'				"isBeneficiaryCode": true,',
'				"isTransferAmount": false,',
'				"isHidden": false,',
'				"allowPartialPayment": false,',
'				"pattern": null,',
'				"hint": null,',
'				"listItems": null',
'			},',
'			{',
'				"fieldID": 95,',
'				"label": "Client Name",',
'				"type": "text",',
'				"mode": "output",',
'				"value": null,',
'				"isRequired": false,',
'				"action": "Confirm",',
'				"isBeneficiaryCode": false,',
'				"isTransferAmount": false,',
'				"isHidden": false,',
'				"allowPartialPayment": false,',
'				"pattern": null,',
'				"hint": null,',
'				"listItems": null',
'			},',
'			{',
'				"fieldID": 96,',
'				"label": "Month",',
'				"type": "text",',
'				"mode": "output",',
'				"value": null,',
'				"isRequired": false,',
'				"action": "Confirm",',
'				"isBeneficiaryCode": false,',
'				"isTransferAmount": false,',
'				"isHidden": false,',
'				"allowPartialPayment": false,',
'				"pattern": null,',
'				"hint": null,',
'				"listItems": null',
'			},',
'			{',
'				"fieldID": 97,',
'				"label": "Year",',
'				"type": "text",',
'				"mode": "output",',
'				"value": null,',
'				"isRequired": false,',
'				"action": "Confirm",',
'				"isBeneficiaryCode": false,',
'				"isTransferAmount": false,',
'				"isHidden": false,',
'				"allowPartialPayment": false,',
'				"pattern": null,',
'				"hint": null,',
'				"listItems": null',
'			},',
'			{',
'				"fieldID": 98,',
'				"label": "Total Amount",',
'				"type": "number",',
'				"mode": "output",',
'				"value": null,',
'				"isRequired": false,',
'				"action": "Confirm",',
'				"isBeneficiaryCode": false,',
'				"isTransferAmount": false,',
'				"isHidden": false,',
'				"allowPartialPayment": false,',
'				"pattern": null,',
'				"hint": null,',
'				"listItems": null',
'			}',
'		],',
'		"accountingEntries": [',
'			{',
'				"productCode": "IDES",',
'				"drCr": "Cr",',
'				"amount": 0.0',
'			}',
'		]',
'	}',
'}'';',
'    l_html CLOB;',
'BEGIN',
'    -- Parse the JSON',
'    APEX_JSON.parse(l_json);',
'    ',
'    -- Initialize the HTML content',
'    l_html := '''';',
'',
'    -- Loop through each field in the JSON',
'    FOR i IN 1..APEX_JSON.get_count(p_path => ''payload.fields'') LOOP',
'        DECLARE',
'            l_field_id    NUMBER := APEX_JSON.get_number(p_path => ''payload.fields[%d].fieldID'', i);',
'            l_label       VARCHAR2(255) := APEX_JSON.get_varchar2(p_path => ''payload.fields[%d].label'', i);',
'            l_type        VARCHAR2(255) := APEX_JSON.get_varchar2(p_path => ''payload.fields[%d].type'', i);',
'            l_mode        VARCHAR2(255) := APEX_JSON.get_varchar2(p_path => ''payload.fields[%d].mode'', i);',
'            l_is_required VARCHAR2(5) := APEX_JSON.get_varchar2(p_path => ''payload.fields[%d].isRequired'', i);',
'            l_item_html   CLOB;',
'        BEGIN',
'            -- Generate the APEX item based on the type and mode',
'            IF l_mode = ''input'' THEN',
'                IF l_type = ''text'' THEN',
'                    l_item_html := APEX_ITEM.TEXT(',
'                                       p_idx => i, ',
'                                       p_value => NULL, ',
'                                       p_item_id => ''P'' || l_field_id, ',
'                                       p_item_label => l_label, ',
'                                       p_required => CASE WHEN l_is_required = ''true'' THEN ''Y'' ELSE ''N'' END',
'                                   );',
'                ELSIF l_type = ''number'' THEN',
'                    l_item_html := APEX_ITEM.NUMBER_FIELD(',
'                                       p_idx => i, ',
'                                       p_value => NULL, ',
'                                       p_item_id => ''P'' || l_field_id, ',
'                                       p_item_label => l_label, ',
'                                       p_required => CASE WHEN l_is_required = ''true'' THEN ''Y'' ELSE ''N'' END',
'                                   );',
'                END IF;',
'            ELSIF l_mode = ''output'' THEN',
'                l_item_html := APEX_ITEM.DISPLAY_ONLY(',
'                                   p_idx => i, ',
'                                   p_value => NULL, ',
'                                   p_item_id => ''P'' || l_field_id, ',
'                                   p_item_label => l_label',
'                               );',
'            END IF;',
'',
'            -- Concatenate the generated HTML',
'            l_html := l_html || l_item_html || ''<br>'';',
'        END;',
'    END LOOP;',
'',
'    -- Output the generated HTML',
'    return l_html;',
'END;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
