begin
wwv_flow_imp_page.create_page(
 p_id=>16
,p_name=>'Datalist With Html'
,p_alias=>'DATALIST-WITH-HTML'
,p_step_title=>'Datalist With Html'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'document.getElementById("P16_AUTO_ITEMS").addEventListener("keyup", function(){',
'  var searchQuery = this.value;',
'  search(searchQuery);',
'});',
'',
'',
'function search(query){',
'  var xhr = new XMLHttpRequest();',
'  xhr.open("GET", "https://your-rest-service-url.com/search?q=" + query, true);',
'  xhr.onreadystatechange = function() {',
'    if (this.readyState === XMLHttpRequest.DONE && this.status === 200) {',
'      var response = JSON.parse(this.responseText);',
'      displayResults(response);',
'    }',
'  };',
'  xhr.send();',
'}',
'',
'',
'function displayResults(results){',
'  var resultsContainer = document.getElementById("results-container");',
'  resultsContainer.innerHTML = "";',
'  for (var i = 0; i < results.length; i++) {',
'    resultsContainer.innerHTML += "<p>" + results[i] + "</p>";',
'  }',
'}',
''))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'25'
);
